<?php declare(strict_types=1);use FastWebsite\Core\View;$v=static fn(string$f):string=>(string)($values[$f]??'');$editing=is_int($itemId);?><section class="admin-page-heading"><div><h1><?=$editing?'Edit facility':'Create facility'?></h1></div><a class="button button-secondary" href="<?=View::escape($baseUrl)?>admin/facilities">Cancel</a></section><?php if($errors!==[]):?><div class="form-alert"><ul><?php foreach($errors as$error):?><li><?=View::escape($error)?></li><?php endforeach;?></ul></div><?php endif;?><form class="content-form" method="post" action="<?=View::escape($baseUrl)?>admin/facilities<?=$editing?'/'.$itemId:''?>"><input type="hidden" name="_token" value="<?=View::escape($csrfToken)?>"><section class="form-section"><div class="form-grid"><div class="form-field span-2"><label for="name">Facility name *</label><input id="name" name="name" required maxlength="255" value="<?=View::escape($v('name'))?>"></div><div class="form-field"><label for="research_unit_id">Research unit *</label><select id="research_unit_id" name="research_unit_id" required><?php foreach($units as$u):?><option value="<?=(int)$u['id']?>"<?=$v('research_unit_id')===(string)$u['id']?' selected':''?>><?=View::escape($u['name'])?></option><?php endforeach;?></select></div><div class="form-field"><label for="facility_type">Type</label><select id="facility_type" name="facility_type"><?php foreach(['laboratory','workshop','studio','computer_lab','testing_facility','field_site','office','other']as$type):?><option value="<?=$type?>"<?=$v('facility_type')===$type?' selected':''?>><?=ucwords(str_replace('_',' ',$type))?></option><?php endforeach;?></select></div><div class="form-field"><label for="location_id">Location</label><select id="location_id" name="location_id"><option value="">Not set</option><?php foreach($locations as$l):?><option value="<?=(int)$l['id']?>"<?=$v('location_id')===(string)$l['id']?' selected':''?>><?=View::escape(implode(', ',array_filter([$l['campus'],$l['building'],$l['room']])))?></option><?php endforeach;?></select></div><div class="form-field"><label for="status">Status</label><select id="status" name="status"><?php foreach(['active','inactive','archived']as$status):?><option value="<?=$status?>"<?=$v('status')===$status?' selected':''?>><?=ucfirst($status)?></option><?php endforeach;?></select></div><div class="form-field span-2"><label for="description">Description</label><textarea id="description" name="description" rows="8"><?=View::escape($v('description'))?></textarea></div></div></section><button class="button button-primary">Save facility</button></form>
